import{_ as t,o,c as a,a3 as d}from"./chunks/framework.Cr9EE2ob.js";const u=JSON.parse('{"title":"POP3 configuration","description":"POP3 configuration for yarilo: RFC 1939 with STLS, UIDL, CAPA and XCLIENT, listener ports, TLS modes and the protocol-level settings behind them.","frontmatter":{"description":"POP3 configuration for yarilo: RFC 1939 with STLS, UIDL, CAPA and XCLIENT, listener ports, TLS modes and the protocol-level settings behind them.","outline":[2,4],"head":[["meta",{"name":"robots","content":"noindex"}],["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/protocols/pop3.html"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/main/protocols/pop3.html"}],["meta",{"property":"og:title","content":"POP3 configuration"}],["meta",{"name":"twitter:title","content":"POP3 configuration"}],["meta",{"property":"og:description","content":"POP3 configuration for yarilo: RFC 1939 with STLS, UIDL, CAPA and XCLIENT, listener ports, TLS modes and the protocol-level settings behind them."}],["meta",{"name":"twitter:description","content":"POP3 configuration for yarilo: RFC 1939 with STLS, UIDL, CAPA and XCLIENT, listener ports, TLS modes and the protocol-level settings behind them."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/main/protocols/pop3.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/main/protocols/pop3.html\\",\\"headline\\":\\"POP3 configuration\\",\\"description\\":\\"POP3 configuration for yarilo: RFC 1939 with STLS, UIDL, CAPA and XCLIENT, listener ports, TLS modes and the protocol-level settings behind them.\\",\\"dateModified\\":\\"2026-10-31T12:43:41.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/main/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"POP3 configuration\\",\\"item\\":\\"https://doc.yarilomail.org/main/protocols/pop3.html\\"}]}]}"]]},"headers":[],"relativePath":"protocols/pop3.md","filePath":"protocols/pop3.md","lastUpdated":1793450621000}'),s={name:"protocols/pop3.md"};function i(l,e,p,r,n,c){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="pop3-configuration" tabindex="-1">POP3 configuration <a class="header-anchor" href="#pop3-configuration" aria-label="Permalink to &quot;POP3 configuration&quot;">​</a></h1><p>Yarilo implements POP3 (RFC 1939) with STLS (RFC 2595), UIDL, CAPA, and XCLIENT.</p><p>Listeners: <code>services.<wbr>pop3s</code> (implicit TLS, port 995) and <code>services.<wbr>pop3</code> (STARTTLS, port 110). See <a href="/main/architecture/services.html">Services configuration</a> for listener-level settings (port, ssl_mode, haproxy_protocol, etc.).</p><hr><h2 id="protocol-pop3" tabindex="-1"><code>protocol.<wbr>pop3</code> <a class="header-anchor" href="#protocol-pop3" aria-label="Permalink to &quot;`protocol.pop3`&quot;">​</a></h2><p>Protocol-level behaviour, shared across both POP3 listeners.</p><h3 id="protocol.pop3.pop3_no_flag_updates" tabindex="-1"><code>pop3_<wbr>no_<wbr>flag_<wbr>updates</code> <a class="header-anchor" href="#protocol.pop3.pop3_no_flag_updates" aria-label="Permalink to &quot;`pop3_no_flag_updates` {#protocol.pop3.pop3_no_flag_updates}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>protocol.pop3.pop3_no_flag_updates</code></dd></dl></div><p><code>false</code> sets <code>\\Seen</code> on retrieved messages at QUIT. <code>true</code> changes no flags on retrieval.</p><h3 id="protocol.pop3.pop3_reuse_xuidl" tabindex="-1"><code>pop3_<wbr>reuse_<wbr>xuidl</code> <a class="header-anchor" href="#protocol.pop3.pop3_reuse_xuidl" aria-label="Permalink to &quot;`pop3_reuse_xuidl` {#protocol.pop3.pop3_reuse_xuidl}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>protocol.pop3.pop3_reuse_xuidl</code></dd></dl></div><p>Use the <code>X-UIDL</code> message header as the UIDL value. Lets mail migrated from Courier, qmail or cPanel keep its UIDLs.</p><h3 id="protocol.pop3.pop3_uidl_format" tabindex="-1"><code>pop3_<wbr>uidl_<wbr>format</code> <a class="header-anchor" href="#protocol.pop3.pop3_uidl_format" aria-label="Permalink to &quot;`pop3_uidl_format` {#protocol.pop3.pop3_uidl_format}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>%u.%v</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>protocol.pop3.pop3_uidl_format</code></dd></dl></div><p>UIDL format string; the variables are listed below.</p><h3 id="protocol.pop3.pop3_uidl_duplicates" tabindex="-1"><code>pop3_<wbr>uidl_<wbr>duplicates</code> <a class="header-anchor" href="#protocol.pop3.pop3_uidl_duplicates" aria-label="Permalink to &quot;`pop3_uidl_duplicates` {#protocol.pop3.pop3_uidl_duplicates}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>rename</code></dd><dt>Type</dt><dd>string</dd><dt>Values</dt><dd><code>allow</code> <code>rename</code></dd><dt>Helm</dt><dd><code>protocol.pop3.pop3_uidl_duplicates</code></dd></dl></div><p><code>allow</code> sends duplicate UIDLs as they are. <code>rename</code> appends a <code>-N</code> suffix so every UIDL is unique.</p><h3 id="protocol.pop3.pop3_enable_last" tabindex="-1"><code>pop3_<wbr>enable_<wbr>last</code> <a class="header-anchor" href="#protocol.pop3.pop3_enable_last" aria-label="Permalink to &quot;`pop3_enable_last` {#protocol.pop3.pop3_enable_last}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>protocol.pop3.pop3_enable_last</code></dd></dl></div><p>Advertise and handle the <code>LAST</code> command (RFC 1460).</p><h3 id="protocol.pop3.pop3_delete_type" tabindex="-1"><code>pop3_<wbr>delete_<wbr>type</code> <a class="header-anchor" href="#protocol.pop3.pop3_delete_type" aria-label="Permalink to &quot;`pop3_delete_type` {#protocol.pop3.pop3_delete_type}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>expunge</code></dd><dt>Type</dt><dd>string</dd><dt>Values</dt><dd><code>expunge</code> <code>flag</code></dd><dt>Helm</dt><dd><code>protocol.pop3.pop3_delete_type</code></dd><dt>See also</dt><dd><a href="/main/protocols/pop3.html#protocol.pop3.pop3_deleted_flag"><code>pop3_deleted_flag</code></a></dd></dl></div><p><code>expunge</code> removes a deleted message from disk at QUIT. <code>flag</code> sets <code>pop3_<wbr>deleted_<wbr>flag</code> instead, so the message stays visible over IMAP.</p><h3 id="protocol.pop3.pop3_deleted_flag" tabindex="-1"><code>pop3_<wbr>deleted_<wbr>flag</code> <a class="header-anchor" href="#protocol.pop3.pop3_deleted_flag" aria-label="Permalink to &quot;`pop3_deleted_flag` {#protocol.pop3.pop3_deleted_flag}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>protocol.pop3.pop3_deleted_flag</code></dd></dl></div><p>IMAP flag set when <code>pop3_<wbr>delete_<wbr>type</code> is <code>flag</code>, for example <code>$POP3Deleted</code>.</p><h3 id="protocol.pop3.pop3_save_uidl" tabindex="-1"><code>pop3_<wbr>save_<wbr>uidl</code> <a class="header-anchor" href="#protocol.pop3.pop3_save_uidl" aria-label="Permalink to &quot;`pop3_save_uidl` {#protocol.pop3.pop3_save_uidl}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>protocol.pop3.pop3_save_uidl</code></dd></dl></div><p>Persist computed UIDLs to a <code>pop3.<wbr>uidl</code> file next to the folder&#39;s index. Later sessions load them, so UIDLs stay the same across index rebuilds and backend changes.</p><h3 id="protocol.pop3.pop3_lock_session" tabindex="-1"><code>pop3_<wbr>lock_<wbr>session</code> <a class="header-anchor" href="#protocol.pop3.pop3_lock_session" aria-label="Permalink to &quot;`pop3_lock_session` {#protocol.pop3.pop3_lock_session}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>protocol.pop3.pop3_lock_session</code></dd></dl></div><p>Create a dotlock at <code>$HOME/<wbr>yarilo-pop3-session.<wbr>lock</code> after login, so another replica on the same PVC cannot serve the user at the same time. Locks older than 10 minutes are stolen.</p><h3 id="pop3-uidl-format-variables" tabindex="-1"><code>pop3_<wbr>uidl_<wbr>format</code> variables <a class="header-anchor" href="#pop3-uidl-format-variables" aria-label="Permalink to &quot;`pop3_uidl_format` variables&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>%u</code></td><td style="text-align:left;">Message UID.</td></tr><tr><td style="text-align:left;"><code>%v</code></td><td style="text-align:left;">Mailbox UIDValidity.</td></tr><tr><td style="text-align:left;"><code>%f</code></td><td style="text-align:left;">Filename (Maildir only).</td></tr><tr><td style="text-align:left;"><code>%g</code></td><td style="text-align:left;">GUID (128-bit hex, dbox/mdbox).</td></tr><tr><td style="text-align:left;"><code>%m</code></td><td style="text-align:left;">MD5 of the filename.</td></tr></tbody></table><p>Common presets:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Format</th><th style="text-align:left;">Result example</th><th style="text-align:left;">Compatible with</th></tr></thead><tbody><tr><td style="text-align:left;"><code>%u.<wbr>%v</code></td><td style="text-align:left;"><code>1234.<wbr>5678</code></td><td style="text-align:left;">yarilo default</td></tr><tr><td style="text-align:left;"><code>%08Xu%08Xv</code></td><td style="text-align:left;"><code>000004D2000016C2</code></td><td style="text-align:left;">the reference</td></tr><tr><td style="text-align:left;"><code>%f</code></td><td style="text-align:left;"><code>1700000000.<wbr>M123P456.<wbr>host:2,S</code></td><td style="text-align:left;">Courier (Maildir)</td></tr></tbody></table><hr><h2 id="soft-delete-flag-mode" tabindex="-1">Soft-delete (flag mode) <a class="header-anchor" href="#soft-delete-flag-mode" aria-label="Permalink to &quot;Soft-delete (flag mode)&quot;">​</a></h2><p>When <code>pop3_<wbr>delete_<wbr>type: flag</code>, messages deleted by a POP3 client are not removed from disk. Instead the flag defined by <code>pop3_<wbr>deleted_<wbr>flag</code> is set, and the message remains visible in IMAP. This allows users to switch between POP3 and IMAP without losing mail.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">protocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  pop3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    pop3_delete_type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">flag</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    pop3_deleted_flag</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$POP3Deleted&quot;</span></span></code></pre></div><hr><h2 id="migration-from-other-servers" tabindex="-1">Migration from other servers <a class="header-anchor" href="#migration-from-other-servers" aria-label="Permalink to &quot;Migration from other servers&quot;">​</a></h2><p>To migrate users from Courier, qmail, or cPanel without changing UIDL values (which would cause POP3 clients to re-download all mail):</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">protocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  pop3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    pop3_reuse_xuidl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    pop3_uidl_format</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%f&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # match the source server&#39;s format</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    pop3_uidl_duplicates</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">rename</span></span></code></pre></div><hr><h2 id="uidl-stability-pop3-save-uidl" tabindex="-1">UIDL stability (<code>pop3_<wbr>save_<wbr>uidl</code>) <a class="header-anchor" href="#uidl-stability-pop3-save-uidl" aria-label="Permalink to &quot;UIDL stability (`pop3_save_uidl`)&quot;">​</a></h2><p>By default, UIDLs are computed fresh each session from <code>pop3_<wbr>uidl_<wbr>format</code>. If the index is rebuilt or a backend migration changes filenames, UIDLs may change - causing POP3 clients to re-download mail they already have.</p><p>Enable <code>pop3_<wbr>save_<wbr>uidl</code> to persist the computed UIDL for each message:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">protocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  pop3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    pop3_save_uidl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>UIDLs are saved to a <code>pop3.<wbr>uidl</code> file next to the folder&#39;s <code>yarilo.<wbr>index</code>, in the index directory (one <code>uid\\tuidl</code> pair per line) at the end of each session via atomic write. On the next session, saved values are loaded and used for existing UIDs; new messages get fresh UIDLs that are then persisted.</p><p>Priority when multiple sources exist: <code>pop3_<wbr>reuse_<wbr>xuidl</code> header → saved index entry → format-computed value.</p><hr><h2 id="session-locking-pop3-lock-session" tabindex="-1">Session locking (<code>pop3_<wbr>lock_<wbr>session</code>) <a class="header-anchor" href="#session-locking-pop3-lock-session" aria-label="Permalink to &quot;Session locking (`pop3_lock_session`)&quot;">​</a></h2><p>In multi-replica deployments (yarilo-pop3 <code>replicas &gt; 1</code> on a shared PVC), two pods could serve the same user simultaneously - one via POP3 and one via IMAP. Enable <code>pop3_<wbr>lock_<wbr>session</code> to prevent this:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">protocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  pop3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    pop3_lock_session</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>After login, the session creates <code>$HOME/<wbr>yarilo-pop3-session.<wbr>lock</code>. A second session for the same user on any pod that shares the filesystem will be rejected with <code>-ERR mailbox already in use</code>. The lock is released when the session ends (QUIT or disconnect). Locks older than the session idle timeout, 10 minutes, are automatically treated as stale and stolen.</p>',57)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
